import * as pdfjs from './assets/pdfjs/pdf.mjs';
import {ContinuousPdfViewer} from './continuous-pdf.js?v=1';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.mjs',import.meta.url).href;
const $=id=>document.getElementById(id),params=new URLSearchParams(location.search),names={qp:'题卷',ms:'评分标准',er:'考官报告',gt:'分数线',ci:'实验说明',pm:'预发布材料'},seasons={m:'2–3月',s:'5–6月',w:'10–11月'};
document.body.classList.toggle('embedded',window.self!==window.top);if(window.self!==window.top)$('provenance').append($('download'));
function progress(){try{const value=JSON.parse(localStorage.getItem('pp-igcse-pages-v2')||'{}');return value&&typeof value==='object'&&!Array.isArray(value)?value:{}}catch{return {}}}
function rememberPage(){if(!current)return;try{const value=progress();value[current.filename]={page:pageNumber,zoom,time:Date.now()};const recent=Object.fromEntries(Object.entries(value).filter(([,v])=>v&&typeof v==='object').sort((a,b)=>(Number(b[1].time)||0)-(Number(a[1].time)||0)).slice(0,100));localStorage.setItem('pp-igcse-pages-v2',JSON.stringify(recent))}catch{}}
let files=[],byName=new Map(),current=null,documentPdf=null,loadingTask=null,pageNumber=1,zoom=1,loadSerial=0;
const viewer=new ContinuousPdfViewer({container:$('viewport'),pagesRoot:$('pages'),pageLabel:$('page'),onPage:number=>{pageNumber=number;rememberPage()},error:error=>{console.error(error);showMessage('部分页面暂未显示，请点击重试。',true);$('retry').hidden=false}});
function showMessage(text,error=false){$('message').textContent=text;$('message').classList.toggle('error',error);$('message').hidden=!text}
function matching(file,type){return ['qp','ms'].includes(file.type)?byName.get(file.filename.replace(/_(qp|ms)_/,'_'+type+'_')):null}
async function open(file){const serial=++loadSerial;if(loadingTask)try{await loadingTask.destroy()}catch{};viewer.destroyDocument();if(documentPdf)try{await documentPdf.destroy()}catch{};documentPdf=null;current=file;pageNumber=1;zoom=1;const previous=progress()[file.filename];if(previous&&Number.isFinite(previous.zoom))zoom=Math.max(.6,Math.min(2.5,previous.zoom));$('attachment').hidden=true;$('retry').hidden=true;showMessage('正在载入连续页面…');const title=(file.subject==='physics'?'Physics 0625':'Computer Science 0478')+' · '+file.year+' '+seasons[file.session]+(file.paper?' · '+file.paper:'')+' · '+names[file.type];$('document-title').textContent=title;document.title=title+' · Pure Practice';const relative=new URL(file.path,location.href);if(relative.origin!==location.origin)throw Error('PDF must be hosted on this website');$('download').href=relative.href;$('download').download=file.filename;$('download').textContent=file.filename.endsWith('.pdf')?'下载 PDF':'下载附件';$('download').hidden=false;$('back').href='igcse.html?'+new URLSearchParams({subject:file.subject,file:file.filename});$('filename').textContent=file.filename+' · '+Math.round(file.bytes/1024)+' KB';$('source').textContent='来源存档：'+file.repository+'；核验日期：2026-10-24。';for(const type of ['qp','ms']){const target=matching(file,type);$(type).disabled=!target;$(type).classList.toggle('active',file.type===type);$(type).onclick=()=>open(target).catch(fail)}const query=new URLSearchParams({subject:file.subject,file:file.filename});history.replaceState(null,'','?'+query);if(window.parent!==window)window.parent.postMessage({type:'igcse-selected',filename:file.filename},location.origin);if(!file.filename.endsWith('.pdf')){showMessage('');$('attachment').hidden=false;$('attachment-link').href=relative.href;$('attachment-link').download=file.filename;return}try{loadingTask=pdfjs.getDocument({url:relative.href,isEvalSupported:false});const next=await loadingTask.promise;if(serial!==loadSerial){await next.destroy();return}documentPdf=next;if(previous&&Number.isFinite(previous.page))pageNumber=Math.max(1,Math.min(next.numPages,Math.floor(previous.page)));showMessage('');await viewer.open(next,{page:pageNumber,zoom});$('zoom').textContent=Math.round(zoom*100)+'%'}catch(error){if(serial===loadSerial)fail(error)}}
function fail(error){showMessage('试卷暂未载入，请点击重试；无需进入第三方网站。',true);$('retry').hidden=false;console.error(error)}
$('prev').onclick=()=>viewer.go(viewer.current-1);$('next').onclick=()=>viewer.go(viewer.current+1);$('zoom-in').onclick=()=>{zoom=Math.min(2.5,Math.round((zoom+.2)*10)/10);viewer.setZoom(zoom);$('zoom').textContent=Math.round(zoom*100)+'%';rememberPage()};$('zoom-out').onclick=()=>{zoom=Math.max(.6,Math.round((zoom-.2)*10)/10);viewer.setZoom(zoom);$('zoom').textContent=Math.round(zoom*100)+'%';rememberPage()};$('fit-width').onclick=()=>{zoom=1;viewer.setZoom(zoom);$('zoom').textContent='100%';rememberPage()};window.addEventListener('keydown',event=>{if(event.target.closest('input,textarea,select,[contenteditable=true]')||event.ctrlKey||event.metaKey||event.altKey)return;const actions={ArrowUp:'prev',PageUp:'prev',ArrowDown:'next',PageDown:'next','+':'zoom-in','=':'zoom-in','-':'zoom-out','0':'fit-width'};const target=actions[event.key];if(target){event.preventDefault();$(target).click()}});$('retry').onclick=()=>current?open(current).catch(fail):location.reload();let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>viewer.resize(),160)});
async function start(){const response=await fetch('data/igcse-online-files.json');if(!response.ok)throw Error('HTTP '+response.status);files=(await response.json()).files;byName=new Map(files.map(file=>[file.filename,file]));let requested=params.get('file');if(!requested&&params.get('pdf')){try{requested=decodeURIComponent(new URL(params.get('pdf')).pathname.split('/').pop())}catch{}}let file=byName.get(requested);const subject=params.get('subject')==='cs'?'cs':'physics';if(!file&&!requested)file=byName.get(subject==='physics'?'0625_w24_qp_42.pdf':'0478_w24_qp_12.pdf');if(!file){showMessage('未找到这份已收集的试卷，请返回列表选择。',true);$('back').href='igcse.html?subject='+subject;return}await open(file)}
start().catch(fail);
